import {Component, HostBinding, OnInit} from '@angular/core';
import {Router} from '@angular/router';
import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../shared';
import {Plugins} from '@capacitor/core';
import 'ocr';
import {HttpClientService} from '../../shared/http-client.service';
import {ModalService} from 'ng-zorro-antd-mobile';
import {environment} from '../../../environments/environment';
import {isNotNullOrUndefined} from 'codelyzer/util/isNotNullOrUndefined';

const { Ocr } = Plugins;
@Component({
    selector: 'app-tube-find-people',
    templateUrl: 'tube-find-people.page.html',
    styleUrls: ['tube-find-people.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class TubeFindPeoplePage implements OnInit {
    boxInfo = {
        censusAddress: '',
        closeMobile: '',
        closeTime: '',
        closeUserName: '',
        inceptMobile: '',
        inceptTime: '',
        inceptUserName: '',
        laboratoryName: '',
        openMobile: '',
        openTime: '',
        openUserName: '',
        patientCount: 0,
        sendMobile: '',
        sendTime: '',
        sendUserName: '',
        tubeBarcode: '',
        tubeId: '',
        tubeState: '',
        tubeType: '',
    };
    personList = [];
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private platform: Platform,
        private deleteModal: ModalService
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
    }

    ionViewWillEnter() {
    }

    // 路由返回
    routeBack() {
       // this.router.navigate(['/BoxList']);
         this.router.navigate(['/tabs/tab1']);
    }
    search(barcode){
        this.ListBoxTube(barcode);
    }

    // 调用后台接口
    // 根据箱查询所有管
    ListBoxTube(barcode){
        this.boxInfo = {
            censusAddress: '',
            closeMobile: '',
            closeTime: '',
            closeUserName: '',
            inceptMobile: '',
            inceptTime: '',
            inceptUserName: '',
            laboratoryName: '',
            openMobile: '',
            openTime: '',
            openUserName: '',
            patientCount: 0,
            sendMobile: '',
            sendTime: '',
            sendUserName: '',
            tubeBarcode: '',
            tubeId: '',
            tubeState: '',
            tubeType: '',
        };
        this.personList = [];
        if (!isNotNullOrUndefined(barcode) || barcode.trim() === ''){
            this.http.showToast('管码为空，请输入管码');
            return;
        }
        const condition = {
            tubeBarcode: barcode
        };
        this.http
            .get(`rcp/api/tube/operate/QueryTubePatientInfo`, condition , '查询采集管中的患者', '查询采集管中的患者', {load: true})
            .subscribe( data => {
                if (data['isSuccess']){
                    this.personList = data['data']['queryPatientInfoVOList'] === null ? []: data['data']['queryPatientInfoVOList'];
                    this.boxInfo = data['data']['queryTubeInfoVO'];
                    console.warn('查询采集管中的患者', this.personList);
               }
            });
    }
}
